{"content": "# restart-humanize.ps1 - ASCII only on purpose.
# Detached (launched via WMI): wait, restart the qqbot host, then send one confirmation
# to the owner through OneBot so he knows the patch is live.
$ErrorActionPreference = 'SilentlyContinue'
$home2 = $env:USERPROFILE
$log = Join-Path $home2 '.dsh-qq\logs\restart-humanize.log'
$msgFile = Join-Path $home2 '.dsh-qq\logs\restart-msg.txt'
$restart = Join-Path $home2 'xqztest\dsh-qq-bot\scripts\Restart-QqBot.ps1'
$send = Join-Path $home2 'xqztest\dsh-qq-bot\scripts\send-once.mjs'
$node = (Get-Command node -ErrorAction SilentlyContinue).Source

function Log($m) { "[$(Get-Date -Format o)] $m" | Add-Content -Encoding UTF8 $log }

Log 'scheduled run start'
Start-Sleep -Seconds 15

if (Test-Path $restart) {
    Log 'restarting qqbot host'
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $restart
    Log "restart exit=$LASTEXITCODE"
} else {
    Log "restart script missing: $restart"
}

Start-Sleep -Seconds 75
Log 'sending confirmation'
if ($node -and (Test-Path $send)) {
    $msg = [System.IO.File]::ReadAllText($msgFile, [System.Text.Encoding]::UTF8).Trim()
    & $node $send 2974630536 $msg 2>&1 | ForEach-Object { Log "send: $_" }
    Log "send exit=$LASTEXITCODE"
} else {
    Log 'node or send-once.mjs missing'
}
Log 'done'
", "file_path": "C:\Users\九幽\xqztest\dsh-qq-bot\scripts\restart-humanize.ps1"}

