{"content": "// restart-humanize.mjs — 脱离 DSH 宿主：等一会儿 → 重启 qqbot 宿主 → 用 OneBot 发一条确认。
// 用 WMI 启动（cmd /c node），不在 dsh 的 job object 里，宿主被杀不连坐。
import { spawn } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'

const HOME = process.env.USERPROFILE || 'C:\\Users\\九幽'
const LOG = path.join(HOME, '.dsh-qq', 'logs', 'restart-humanize.log')
const MSG = path.join(HOME, '.dsh-qq', 'logs', 'restart-msg.txt')
const RESTART = path.join(HOME, 'xqztest', 'dsh-qq-bot', 'scripts', 'Restart-QqBot.ps1')
const SEND = path.join(HOME, 'xqztest', 'dsh-qq-bot', 'scripts', 'send-once.mjs')
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const log = (m) => fs.appendFileSync(LOG, `[${new Date().toISOString()}] ${m}\n`, 'utf8')

log('scheduled run start')
await sleep(12000)

log('restarting qqbot host')
try {
  const p = spawn('powershell.exe', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', RESTART], {
    detached: true,
    stdio: 'ignore',
    windowsHide: true,
  })
  p.unref()
  log('restart spawned pid=' + p.pid)
} catch (error) {
  log('restart spawn failed: ' + String(error))
}

await sleep(90000)
log('sending confirmation')
try {
  const msg = fs.readFileSync(MSG, 'utf8').trim()
  const s = spawn('node', [SEND, '2974630536', msg], { detached: true, stdio: 'ignore', windowsHide: true })
  s.unref()
  log('send spawned pid=' + s.pid)
} catch (error) {
  log('send failed: ' + String(error))
}
await sleep(5000)
log('done')
", "file_path": "C:\Users\九幽\.dsh-qq\scripts\restart-humanize.mjs"}

