{"content": "param([string]$Action = 'now')
# media.ps1 - 系统媒体控制（Windows 5.1 专用，pwsh7 的 WinRT 绑定不一样）
# 用法: powershell -NoProfile -File media.ps1 -Action now|playpause|next|prev
$ErrorActionPreference = 'Stop'

function Await-Op($op, $type) {
  $asTask = ([System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object {
      $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and
      $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1'
    })[0]
  $netTask = $asTask.MakeGenericMethod($type).Invoke($null, @($op))
  $null = $netTask.Wait(-1)
  $netTask.Result
}

Add-Type -AssemblyName System.Runtime.WindowsRuntime
$null = [Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager, Windows.Media.Control, ContentType = WindowsRuntime]

if ($Action -eq 'now') {
  $mgr = Await-Op ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager]::RequestAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager])
  $session = $mgr.GetCurrentSession()
  if ($null -eq $session) { '{"ok":false,"error":"no active media session"}'; exit 0 }
  $props = Await-Op ($session.TryGetMediaPropertiesAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionMediaProperties])
  $info = $session.GetPlaybackInfo()
  $out = [ordered]@{
    ok      = $true
    app     = $session.SourceAppUserModelId
    title   = $props.Title
    artist  = $props.Artist
    album   = $props.AlbumTitle
    status  = $info.PlaybackStatus.ToString()
  }
  $out | ConvertTo-Json -Compress
  exit 0
}

if ($Action -eq 'sessions') {
  $mgr = Await-Op ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager]::RequestAsync()) ([Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager])
  $mgr.GetSessions() | ForEach-Object { $_.SourceAppUserModelId }
  exit 0
}

