{"content": "param([string]$ProcessName = 'SodaMusic', [int]$Depth = 3)
# ui-probe.ps1 - dump UIA tree of a window (Windows PowerShell 5.1)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
$root = [System.Windows.Automation.AutomationElement]::RootElement
$cond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ProcessIdProperty, (Get-Process $ProcessName | Sort-Object StartTime | Select-Object -Last 1).Id)
$win = $root.FindFirst([System.Windows.Automation.TreeScope]::Children, $cond)
if ($null -eq $win) { '{"ok":false,"error":"window not found"}'; exit 0 }

function Walk($el, $level) {
  if ($level -gt $Depth) { return }
  $walker = [System.Windows.Automation.TreeWalker]::ControlViewWalker
  $child = $walker.GetFirstChild($el)
  while ($null -ne $child) {
    $name = $child.Current.Name
    $type = $child.Current.ControlType.ProgrammaticName
    $autoId = $child.Current.AutomationId
    $cls = $child.Current.ClassName
    $r = $child.Current.BoundingRectangle
    if ($name -ne '' -or $autoId -ne '') {
      ('  ' * $level) + "$type | name=$name | id=$autoId | cls=$cls | rect=$([int]$r.X),$([int]$r.Y),$([int]$r.Width)x$([int]$r.Height)"
    }
    Walk $child ($level + 1)
    $child = $walker.GetNextSibling($child)
  }
}
Walk $win 0
", "file_path": "C:\Users\九幽\.dsh-qq\scripts\ui-probe.ps1"}

