{"content": "#!/usr/bin/env node
// cdp.mjs — 用 Chrome DevTools 协议控制浏览器（Node 22，自带 WebSocket，无依赖）
// 用法：
//   node cdp.mjs open <url>              新开标签页并等待加载
//   node cdp.mjs shot <png路径>          截当前标签页
//   node cdp.mjs text                    取页面可见文字（前 4000 字）
//   node cdp.mjs click <x> <y>           在页面坐标点一下
//   node cdp.mjs type <文本>             往当前焦点输入文字
//   node cdp.mjs eval <js表达式>         在页面里求值
//   node cdp.mjs tabs                    列出标签页
const PORT = process.env.CDP_PORT || 9222
const BASE = `http://127.0.0.1:${PORT}`

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

async function listTargets() {
  const res = await fetch(`${BASE}/json/list`)
  if (!res.ok) throw new Error('chrome devtools not reachable on ' + PORT)
  return res.json()
}

async function pageTarget() {
  const list = await listTargets()
  const pages = list.filter((t) => t.type === 'page' && t.webSocketDebuggerUrl)
  if (!pages.length) throw new Error('no page target; run: node cdp.mjs open about:blank')
  return pages[0]
}

function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl)
    const pending = new Map()
    let nextId = 1
    ws.addEventListener('open', () => {
      resolve({
        send(method, params = {}) {
          const id = nextId++
          ws.send(JSON.stringify({ id, method, params }))
          return new Promise((res, rej) => {
            pending.set(id, { res, rej })
            setTimeout(() => {
              if (pending.has(id)) {
                pending.delete(id)
                rej(new Error('timeout: ' + method))
              }
            }, 30000)
          })
        },
        close() { ws.close() },
      })
    })
    ws.addEventListener('message', (ev) => {
      const msg = JSON.parse(ev.data)
      if (msg.id && pending.has(msg.id)) {
        const { res, rej } = pending.get(msg.id)
        pending.delete(msg.id)
        if (msg.error) rej(new Error(msg.error.message))
        else res(msg.result)
      }
    })
    ws.addEventListener('error', (e) => reject(new Error('ws error')))
  })
}

async function main() {
  const [cmd, ...args] = process.argv.slice(2)

  if (cmd === 'tabs') {
    const list = await listTargets()
    for (const t of list) console.log(`${t.type}\t${t.title}\t${t.url}`)
    return
  }

  if (cmd === 'open') {
    const url = args[0] || 'about:blank'
    const res = await fetch(`${BASE}/json/new?${encodeURIComponent(url)}`, { method: 'PUT' })
    const target = await res.json()
    const c = await connect(target.webSocketDebuggerUrl)
    await c.send('Page.enable')
    await c.send('Runtime.enable')
    await sleep(2500)
    const info = await c.send('Runtime.evaluate', {
      expression: 'JSON.stringify({title: document.title, url: location.href})',
      returnByValue: true,
    })
    console.log(info.result.value)
    c.close()
    return
  }

  const target = await pageTarget()
  const c = await connect(target.webSocketDebuggerUrl)
  await c.send('Page.enable')
  await c.send('Runtime.enable')

  if (cmd === 'shot') {
    const out = args[0] || 'shot.png'
    const res = await c.send('Page.captureScreenshot', { format: 'png' })
    const fs = await import('node:fs')
    fs.writeFileSync(out, Buffer.from(res.data, 'base64'))
    console.log(out)
  } else if (cmd === 'text') {
    const res = await c.send('Runtime.evaluate', {
      expression: 'document.body ? document.body.innerText.slice(0, 4000) : ""',
      returnByValue: true,
    })
    console.log(res.result.value || '')
  } else if (cmd === 'eval') {
    const res = await c.send('Runtime.evaluate', {
      expression: args.join(' '),
      returnByValue: true,
      awaitPromise: true,
    })
    console.log(JSON.stringify(res.result.value ?? res.result.description ?? null))
  } else if (cmd === 'click') {
    const x = Number(args[0])
    const y = Number(args[1])
    for (const type of ['mousePressed', 'mouseReleased']) {
      await c.send('Input.dispatchMouseEvent', { type, x, y, button: 'left', clickCount: 1 })
    }
    console.log(`clicked ${x},${y}`)
  } else if (cmd === 'type') {
    const text = args.join(' ')
    for (const ch of text) {
      await c.send('Input.dispatchKeyEvent', { type: 'char', text: ch })
    }
    console.log('typed ' + text.length + ' chars')
  } else {
    console.log('unknown command: ' + cmd)
  }
  c.close()
}

main().catch((e) => {
  console.error('error: ' + e.message)
  process.exit(1)
})
