{"content": "param(
  [Parameter(Mandatory = $true)][string]$Action,
  [int]$X = 0,
  [int]$Y = 0,
  [string]$Text = '',
  [string]$Out = 'C:\Users\九幽\.dsh-qq\media\ui-shot.png'
)
# ui.ps1 - 桌面操控（Windows PowerShell 5.1）
# 用法:
#   -Action windows            列出有窗口的进程
#   -Action shot               截整屏到 $Out
#   -Action move -X 100 -Y 200
#   -Action click -X 100 -Y 200
#   -Action dblclick -X 100 -Y 200
#   -Action type -Text "hello"
#   -Action key -Text "ENTER"   (ENTER/TAB/ESC/BACKSPACE/CTRL+A 之类)
#   -Action focus -Text "SodaMusic"   把某个进程的窗口提到前面
$ErrorActionPreference = 'Stop'

if ($Action -eq 'windows') {
  Get-Process | Where-Object { $_.MainWindowTitle -ne '' } |
    Select-Object Id, ProcessName, MainWindowTitle |
    ForEach-Object { "$($_.Id)`t$($_.ProcessName)`t$($_.MainWindowTitle)" }
  exit 0
}

if ($Action -eq 'shot') {
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'shot.ps1') -Out $Out
  exit 0
}

$sig = @'
using System;
using System.Runtime.InteropServices;
public class Ui {
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
  [DllImport("user32.dll")] public static extern void mouse_event(uint f, uint dx, uint dy, uint d, UIntPtr e);
  [DllImport("user32.dll")] public static extern void keybd_event(byte bVk, byte bScan, uint f, UIntPtr e);
  [DllImport("user32.dll")] public static extern IntPtr FindWindow(string cls, string name);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int cmd);
  public const uint LEFTDOWN = 0x0002, LEFTUP = 0x0004;
  public const uint KEYUP = 0x0002;
}
'@
Add-Type -TypeDefinition $sig

function Send-Text([string]$s) {
  foreach ($ch in $s.ToCharArray()) {
    $code = [int]$ch
