  [DllImport("kernel32.dll")] public static extern uint GetCurrentThreadId();
  [DllImport("user32.dll")] public static extern bool AttachThreadInput(uint a, uint b, bool attach);
  [DllImport("user32.dll")] public static extern IntPtr GetWindow(IntPtr h, uint cmd);

  // 后台进程直接 SetForegroundWindow 常常被系统拒绝，先挂到前台线程再切
  public static bool ForceForeground(IntPtr h) {
    if (h == IntPtr.Zero) return false;
    ShowWindow(h, 9);
    uint pid;
    uint fgThread = GetWindowThreadProcessId(GetForegroundWindow(), out pid);
    uint myThread = GetCurrentThreadId();
    bool ok = false;
    if (fgThread != myThread) AttachThreadInput(myThread, fgThread, true);
    try {
      SetForegroundWindow(h);
      ok = (GetForegroundWindow() == h);
      if (!ok) { SetForegroundWindow(GetForegroundWindow()); SetForegroundWindow(h); }
    } finally {
      if (fgThread != myThread) AttachThreadInput(myThread, fgThread, false);
    }
    return ok || GetForegroundWindow() == h;
  }", "old_string": "  [DllImport("user32.dll")] public static extern IntPtr FindWindow(string cls, string name);
