{"content": "#!/usr/bin/env node
// checkpoint-watch.mjs — 盯着会话文件，DSH 一旦压缩上下文（compaction/start），
// 先把最近这段对话抽出来写进 JOURNAL 的「自动检查点」，不靠模型临场想起来。
// 用法: node checkpoint-watch.mjs [--simulate]
import fs from 'node:fs'
import path from 'node:path'

const HOME = process.env.USERPROFILE || 'C:\\Users\\九幽'
const SESS = path.join(HOME, '.dsh-qq', 'sessions')
const JOURNAL = path.join(HOME, '.dsh-qq', 'memory-repo', 'short', 'JOURNAL.md')
const STATE = path.join(HOME, '.dsh-qq', 'checkpoint-watch.json')
const LOG = path.join(HOME, '.dsh-qq', 'logs', 'checkpoint-watch.log')
const MAX_ITEMS = 14
const MAX_CHARS = 220

const log = (m) => {
  try {
    fs.mkdirSync(path.dirname(LOG), { recursive: true })
    fs.appendFileSync(LOG, `[${new Date().toISOString()}] ${m}\n`, 'utf8')
  } catch {}
}

function newestSession() {
  let best = null
  const walk = (dir) => {
    let ents = []
    try { ents = fs.readdirSync(dir, { withFileTypes: true }) } catch { return }
    for (const e of ents) {
      const p = path.join(dir, e.name)
      if (e.isDirectory()) walk(p)
      else if (e.name === 'session.v4.jsonl') {
        const st = fs.statSync(p)
        if (!best || st.mtimeMs > best.mtimeMs) best = { file: p, mtimeMs: st.mtimeMs, size: st.size }
      }
    }
  }
  walk(SESS)
  return best
}

function readState() {
  try { return JSON.parse(fs.readFileSync(STATE, 'utf8')) } catch { return { file: null, lines: 0 } }
}
function writeState(s) { fs.writeFileSync(STATE, JSON.stringify(s, null, 1), 'utf8') }

const clip = (s) => {
  const one = String(s).replace(/\s+/g, ' ').trim()
  return one.length > MAX_CHARS ? one.slice(0, MAX_CHARS) + '…' : one
}

function textOf(ev) {
  if (ev.type === 'user/message') {
    const parts = (ev.data?.content ?? []).filter((c) => c.type === 'text').map((c) => c.text)
    return parts.join(' ').replace(/<\/?user_message[^>]*>/g, '').trim()
  }
  if (ev.type === 'assistant/message') {
    const parts = (ev.data?.message?.content ?? []).filter((c) => c.type === 'text').map((c) => c.text)
    return parts.join(' ').trim()
  }
  return ''
}

function writeCheckpoint(lines, reason) {
  const items = []
  for (const line of lines) {
    let ev
    try { ev = JSON.parse(line) } catch { continue }
    const t = textOf(ev)
    if (t) items.push(`${ev.type === 'user/message' ? '他' : '我'}：${clip(t)}`)
  }
  const tail = items.slice(-MAX_ITEMS)
  if (!tail.length) { log('no text to checkpoint'); return false }
  const stamp = new Date().toLocaleString('zh-CN')
  const block = [
    '',
    `## 自动检查点 ${stamp}（${reason}）`,
    '',
    '> 上下文压缩前自动写的，压缩之后翻这里补记忆。',
    '',
    ...tail.map((x) => `- ${x}`),
    '',
  ].join('\n')
  fs.appendFileSync(JOURNAL, block, 'utf8')
  log(`checkpoint written: ${tail.length} items (${reason})`)
  return true
}

const main = () => {
  const simulate = process.argv.includes('--simulate')
  const cur = newestSession()
  if (!cur) { log('no session file'); return }
  const state = readState()

  if (simulate) {
    const all = fs.readFileSync(cur.file, 'utf8').split(/\r?\n/)
    writeCheckpoint(all, '手动试验')
    return
  }

  if (state.file !== cur.file) {
    // 换了会话：旧文件里漏掉的压缩就算了，新文件从头盯
    writeState({ file: cur.file, lines: 0 })
    log('switched to ' + cur.file)
    return
  }

  const all = fs.readFileSync(cur.file, 'utf8').split(/\r?\n/)
  if (all.length <= state.lines) return

  const fresh = all.slice(state.lines)
  const compaction = fresh.filter((l) => l.includes('compaction/start'))
  if (compaction.length > 0) {
    writeCheckpoint(all, '上下文即将压缩')
  }
  writeState({ file: cur.file, lines: all.length })
}

main()
