{"content": "#!/usr/bin/env node
// starmap3d.mjs — 把 mind/memory.json 渲成一张能转的记忆银河（Three.js 单文件 HTML）
// 用法: node starmap3d.mjs [输出路径]
import fs from 'node:fs'
import path from 'node:path'

const HOME = process.env.USERPROFILE || 'C:\\Users\\九幽'
const MIND = path.join(HOME, '.dsh-qq', 'memory-repo', 'mind', 'memory.json')
const OUT = process.argv[2] || path.join('E:', 'Obsidian Vault', '晚晚记忆', '记忆银河.html')

const db = JSON.parse(fs.readFileSync(MIND, 'utf8'))
const kindColor = { fact: '#ffcf8a', person: '#ff9fc4', principle: '#ffe08a', event: '#a8d8ff' }

const nodes = db.entries
  .filter((e) => !e.forgotten)
  .map((e, i) => ({
    id: e.id,
    t: e.t,
    kind: e.kind || 'fact',
