const STALE = /^（已过时|^\(已过时|已过时/

const report = { missingEvidence: [], stale: [], total: 0 }
const json = process.argv.includes('--json')

for (const file of FILES) {
  if (!fs.existsSync(file)) continue
  const raw = fs.readFileSync(file, 'utf8')
  const entries = raw.split(/\n§\n/).map((s) => s.trim()).filter(Boolean)
  for (const e of entries) {
    // 跳过纯标题/分隔
    if (e.length < 8) continue
    report.total++
    const first = e.split(/\n/)[0]
    if (STALE.test(first)) report.stale.push(first.slice(0, 60))
    else if (!EVIDENCE.test(e)) report.missingEvidence.push(first.slice(0, 60))
  }
}

if (json) {
  console.log(JSON.stringify(report, null, 1))
} else {
  console.log(`精点共 ${report.total} 条｜缺原话 ${report.missingEvidence.length} 条｜已过时 ${report.stale.length} 条`)
  if (report.missingEvidence.length) {
    console.log('\n缺原话（补一句他说过的就行）：')
    for (const m of report.missingEvidence) console.log('  - ' + m)
  }
  if (report.stale.length) {
    console.log('\n已过时（还被引用就该删或合并）：')
    for (const m of report.stale) console.log('  - ' + m)
  }
}
