{"command": "$OutputEncoding=[System.Text.UTF8Encoding]::new($false); [Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false)
$out='C:\Users\九幽\.dsh-qq\media\yiren'
New-Item -ItemType Directory -Force -Path $out | Out-Null
$base='手机 App 图标，国风道系风格，深靛蓝底色，月白色细线条，少量朱砂红点缀，符箓与八卦的质感，简洁扁平，方形构图，居中，无文字'
$items = @(
 @{n='chat';    p="$base，中心是一个对话框与几道符箓笔触"},
 @{n='camera';  p="$base，中心是相机镜头，外圈一圈八卦环"},
 @{n='photos';  p="$base，中心是水墨远山与一轮浅月"},
 @{n='music';   p="$base，中心是一枚音符，缠着一道炁的弧线"},
 @{n='browser'; p="$base，中心是罗盘，指针偏向一侧"},
 @{n='settings';p="$base，中心是齿轮，内嵌一个太极"},
 @{n='phone';   p="$base，中心是听筒，尾部拖一道炁流"}
)
foreach($i in $items){
  $r = node C:\Users\九幽\.dsh-qq\scripts\agnes.mjs image $i.p --out $out --size 1024x1024 2>&1 | Out-String
  $j = $r.Trim() | ConvertFrom-Json -ErrorAction SilentlyContinue
  if ($j -and $j.ok) {
    $target = Join-Path $out ($i.n + '.png')
    Move-Item $j.path $target -Force
    "OK $($i.n)"
  } else { "FAIL $($i.n): $($r.Trim())" }
}", "description": "Generate seven themed icons", "timeoutMs": 300000}

